#include "GrabberRenderedStore.hpp"
#include <iostream>
using namespace udm;
int main(int argc,char** argv){try{if(argc!=2)return 2;std::string url=argv[1];auto root=fs::temp_directory_path()/wide("udm-rendered-crawler-"+guid());Manager manager(root);manager.state["Settings"]["ProxyMode"]="Connect directly";manager.state["Settings"]["Retries"]=0;manager.save();Json project={{"Id",guid()},{"Name","Rendered crawler"},{"StartUrl",url},{"FileInclude","*.zip"},{"FileExclude","blocked*"},{"Depth",1},{"MaxPages",10},{"Links",Json::array()}};manager.saveProject(project);Cancel cancel;int passed=0;auto check=[&](bool ok){if(!ok)throw std::runtime_error("Rendered crawler assertion failed at "+std::to_string(passed));++passed;};
 auto baseline=runGrabber(manager,project,cancel);check(baseline["Links"].empty());project=baseline;
 auto request=beginRenderedGrabberRequest(manager,str(project,"Id"));auto origin=Url(url).origin;Json snapshot={{"version",1},{"url",url},{"baseUrl",url},{"title","Fixture"},{"documentId","document"},{"tabId",1},{"frameId",0},{"visited",4},{"truncated",false},{"references",Json::array()}};for(const char* name:{"runtime.zip","blocked.zip","wrong.pdf"})snapshot["references"].push_back({{"url",origin+"/"+name},{"kind","link"},{"description","Browser-created file"}});request["snapshot"]=snapshot;completeRenderedGrabberRequest(manager,request);
 auto found=runGrabber(manager,project,cancel);check(found["Links"].size()==1);check(str(found["Links"][0],"Url")==origin+"/runtime.zip");check(num(found["Links"][0],"Size")==4);check(str(found["Links"][0],"Description")=="Browser-created file");check(!found.contains("snapshot")&&!found.contains("protectedSnapshot"));check(str(found["ExploreState"],"Signature").find("|rendered:")!=std::string::npos);
 auto changed=found;changed["FileInclude"]="*.pdf";bool rejected=false;try{runGrabber(manager,changed,cancel);}catch(...){rejected=true;}check(rejected);Manager restarted(root);check(!loadRenderedGrabberSnapshot(restarted,found).empty());std::cout<<"PASS "<<passed<<" rendered crawler checks\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
